<section class="site-page-heading"><div class="container"><p class="site-kicker"><a href="/">首页</a><?php foreach ($breadcrumb as $crumb): ?> / <a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::categoryLink($crumb)) ?>"><?= \FangdaysCMS\Cms\View::e($crumb['name']) ?></a><?php endforeach; ?></p><?php if ($category['thumbnail_path']): ?><img class="site-category-thumbnail" src="<?= \FangdaysCMS\Cms\View::e($category['thumbnail_path']) ?>" alt=""><?php endif; ?><h1><?= \FangdaysCMS\Cms\View::e($category['single_title']) ?></h1><?php if ($category['banner_path']): ?><img class="site-category-banner" src="<?= \FangdaysCMS\Cms\View::e($category['banner_path']) ?>" alt=""><?php endif; ?></div></section>
<div class="container py-5"><div class="row justify-content-center"><article class="col-lg-9">
  <?php if ($cover): ?><img class="site-post-cover mb-4" src="<?= \FangdaysCMS\Cms\View::e($cover['path']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($category['single_title']) ?>"><?php endif; ?>
  <div class="site-article-body"><?= \FangdaysCMS\Cms\RichText::render($category['single_body'], $category['single_body_format']) ?></div>
  <?php if ($gallery): ?><section class="site-post-gallery mt-4" aria-label="单页多图"><h2>图片集</h2><div class="site-post-gallery-grid"><?php foreach ($gallery as $image): ?><figure><img src="<?= \FangdaysCMS\Cms\View::e($image['path']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($image['title'] ?: $image['original_name']) ?>" loading="lazy"><figcaption><?= \FangdaysCMS\Cms\View::e($image['title'] ?: $image['original_name']) ?></figcaption></figure><?php endforeach; ?></div></section><?php endif; ?>
  <?php if ($attachment): ?><p class="site-post-attachment mt-4"><a href="/category/<?= \FangdaysCMS\Cms\View::e($category['slug']) ?>/attachment">下载附件：<?= \FangdaysCMS\Cms\View::e($attachment['original_name']) ?></a> <small>（<?= (int) $attachment['bytes'] ?> 字节）</small></p><?php endif; ?>
  <?php if ($extra_fields): ?><dl class="site-post-fields mt-4 border-top pt-3"><?php foreach ($extra_fields as $field): ?><div class="row py-2"><dt class="col-sm-3"><?= \FangdaysCMS\Cms\View::e($field['label']) ?></dt><dd class="col-sm-9 mb-0"><?php if ($field['type'] === 'editor'): ?><?= \FangdaysCMS\Cms\RichText::render($field['value'], 'html') ?><?php elseif ($field['type'] === 'image'): ?><img class="site-post-cover" src="<?= \FangdaysCMS\Cms\View::e($field['value']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($field['label']) ?>"><?php else: ?><?= nl2br(\FangdaysCMS\Cms\View::e($field['value'])) ?><?php endif; ?></dd></div><?php endforeach; ?></dl><?php endif; ?>
  <p class="mt-5"><a href="/">← 返回首页</a></p>
</article></div></div>
